import {roles,capabilities,isManagement,canViewTask} from './policy.mjs?v=3';
import {escapeHTML as esc,grams,fa} from './core.mjs?v=3';
import {routeTemplates,certaintyNames} from './factory-model.mjs?v=3';
export const products=[
 {id:'constellation-100',name:'شمش نقره ضربی',collection:'Constellation',key:'mint',metal:'نقره',purity:'999.9',weights:[10,20,31.1035,50,100],route:'mint'},
 {id:'celestial-1',name:'شمش طلای ضربی',collection:'Celestial',key:'gold',metal:'طلا',purity:'995.0',weights:[1,5,10,20,31.1035],route:'mint'},
 {id:'silver-coin',name:'سکه نقره',collection:'Silver Coin',key:'coin',metal:'نقره',purity:'999.9',weights:[31.1035],route:'mint'},
 {id:'artwork-100',name:'شمش طلای هنری',collection:'Artwork',key:'art',metal:'طلا',purity:'995.0',weights:[50,100],route:'mint'},
 {id:'courtyard-250',name:'شمش طلای کست',collection:'The Courtyard',key:'courtyard',metal:'طلا',purity:'995.0',weights:[250,500,1000],route:'cast'},
 {id:'argentum-granules',name:'ساچمه نقره',collection:'Argentum',key:'granules',metal:'نقره',purity:'999.9',weights:[1000,2000,5000],route:'granules',targetKind:'mass'},
 {id:'argentum-cast',name:'شمش کست نقره',collection:'Argentum',key:'silver',metal:'نقره',purity:'999.9',weights:[250,500,1000],route:'cast'},
 {id:'investment-100',name:'نقره تقسیم‌پذیر',collection:'Investment',key:'investment',metal:'نقره',purity:'990.0',weights:[100],route:'mint'},
 {id:'bespoke',name:'بسته‌بندی سفارشی',collection:'Bespoke Editions',key:'bespoke',metal:'طلا',purity:'995.0',weights:[1,5,10,20,31.1035],route:'mint'},
];
const options=(entries,value)=>entries.map(([key,label])=>`<option value="${esc(key)}" ${String(key)===String(value)?'selected':''}>${esc(label)}</option>`).join('');
const peopleOptions=(value,filter=()=>true)=>options(Object.entries(roles).filter(([id])=>filter(id)).map(([id,r])=>[id,r.name]),value);
export function createMarkup(d,c){
 const p=products.find(p=>p.id===d.preset),isProduct=d.type==='production',chosenRoute=d.path||p?.route||'mint',stages=routeTemplates[isProduct?chosenRoute:'general'],presets=isProduct?products:c.presets.general;
 return `<form id="task-create-form" novalidate><div class="form-error" role="alert" id="task-create-error"></div><div class="form-tabs" role="tablist" aria-label="نوع تسک جدید">${[['production','محصول'],['general','عمومی']].map(([type,label])=>`<button type="button" role="tab" aria-selected="${d.type===type}" class="${d.type===type?'is-active':''}" data-action="create-type" data-type="${type}" ${type==='production'&&!capabilities.production(c.actor)?'disabled':''}>${label}</button>`).join('')}</div><div class="preset-grid">${presets.map(x=>`<button type="button" class="preset-choice ${d.preset===x.id?'is-active':''}" data-action="preset" data-id="${x.id}" aria-pressed="${d.preset===x.id}"><img src="${esc(isProduct?c.media[x.key]:x.image)}" alt=""><span><b>${esc(x.name)}</b><small>${esc(x.collection||x.subtitle)}</small></span></button>`).join('')}<button type="button" class="preset-choice other ${d.preset==='other'?'is-active':''}" data-action="preset" data-id="other"><span>＋ سایر موارد · توضیح الزامی</span></button></div>${d.preset?`<div class="field"><label for="task-title">عنوان کار</label><input id="task-title" name="title" value="${esc(d.title)}" maxlength="100" required></div><div class="field"><label for="task-description">توضیح ${d.preset==='other'?'· الزامی':''}</label><textarea id="task-description" name="description" ${d.preset==='other'?'required':''}>${esc(d.description||'')}</textarea></div>${isProduct?`<div class="field-row"><div class="field"><label for="target-kind">معنای هدف</label><select id="target-kind" name="targetKind">${options([['count','تعداد محصول مشخص'],['mass','مقدار ماده به گرم']],d.targetKind||p?.targetKind||'count')}</select></div>${p?`<div class="field"><label for="unit-weight">وزن هر محصول · گرم</label><select id="unit-weight" name="unitWeight">${options(p.weights.map(w=>[w,grams(w)+' گرم']),d.unitWeight||p.weights[0])}</select></div>`:''}</div><div class="field-row"><div class="field"><label for="target-quantity">تعداد هدف · برای هدف تعدادی</label><input id="target-quantity" name="quantity" inputmode="numeric" value="${esc(d.quantity??'')}"></div><div class="field"><label for="target-weight">وزن کل هدف · گرم</label><input id="target-weight" name="weight" inputmode="decimal" value="${esc(d.weight??'')}" required></div></div><div class="field-row"><div class="field"><label for="task-metal">فلز هدف</label><select id="task-metal" name="material">${options([['نقره','نقره'],['طلا','طلا']],d.material||p?.metal||'نقره')}</select></div><div class="field"><label for="task-purity">عیار هدف · در هزار</label><input id="task-purity" name="purity" inputmode="decimal" value="${esc(d.purity||p?.purity||'')}"></div></div><div class="field"><label for="task-finish">مشخصات فینیش و نتیجه مورد انتظار</label><input id="task-finish" name="finish" value="${esc(d.finish||'')}"></div><details><summary>خروجی‌های برنامه‌ریزی‌شده بیشتر · اختیاری</summary><div class="op-target-rows">${[0,1,2].map(i=>`<div class="field-row"><div class="field"><label>خروجی ${i+1}<input name="target.${i}.sku" value="${esc(d.targets?.[i]?.sku||'')}"></label></div><div class="field"><label>تعداد هدف<input name="target.${i}.quantity" inputmode="numeric" value="${esc(d.targets?.[i]?.quantity||'')}"></label></div><div class="field"><label>وزن هر واحد · گرم<input name="target.${i}.unitWeight" inputmode="decimal" value="${esc(d.targets?.[i]?.unitWeight||'')}"></label></div></div>`).join('')}</div><small>این‌ها هدف‌اند؛ موجودی فقط با ثبت خروجی واقعی تغییر می‌کند.</small></details><details open><summary>مسیر آماده و پایان مورد انتظار</summary><div class="field"><label for="task-path">مسیر کار</label><select id="task-path" name="path">${options(Object.keys(routeTemplates).filter(k=>k!=='general').map(k=>[k,{mint:'ضرب و بسته‌بندی',cast:'کست',granules:'گرانول',silverRefine:'پالایش نقره و کلرید',electro:'الکتروریفاینینگ نقره',goldRefine:'پالایش طلا'}[k]]),chosenRoute)}</select></div><div class="field"><label for="task-end">معنای پایان کار</label><select id="task-end" name="endStage">${options(stages.map(x=>[x,x]),d.endStage||stages.at(-1))}</select></div><p class="route-preview">${stages.map(esc).join(' ← ')}</p><small>مرحله‌ها مستقل و تکرارپذیرند؛ نوبت‌های جزئی می‌توانند هم‌زمان در فرایندهای مختلف باشند.</small></details>`:''}<details open><summary>مسئول، تیم و پیش‌نیاز</summary><div class="field-row"><div class="field"><label for="task-owner">مسئول کار</label><select id="task-owner" name="ownerId">${peopleOptions(d.ownerId||c.actor,id=>!isProduct||capabilities.production(id))}</select></div>${isProduct?`<div class="field"><label for="task-discrepancy">مسئول اصلاح موجودی همین تسک</label><select id="task-discrepancy" name="discrepancyOwnerId">${peopleOptions(d.discrepancyOwnerId||d.ownerId||c.actor,id=>!isProduct||capabilities.production(id))}</select></div>`:''}</div><details><summary>انتخاب همکاران و مسئولیت هر نفر</summary><div class="op-team-choices">${Object.entries(roles).filter(([id])=>id!==c.actor&&id!=='office'&&(!isProduct||capabilities.production(id))).map(([id,r])=>`<div><label><input type="checkbox" name="team" value="${id}" ${(d.team||[]).includes(id)?'checked':''}>${esc(r.name)}</label><input name="responsibility.${id}" aria-label="مسئولیت ${esc(r.name)}" placeholder="مسئولیت این همکار" value="${esc(d.responsibilities?.[id]||'')}"></div>`).join('')}</div></details><small>پیشنهاد همکار در درخواست، عضویت فعال نمی‌سازد. پس از تأیید کار، هر همکار دعوت را خودش قبول می‌کند.</small><div class="field"><label for="task-dependencies">پیش‌نیازهای اجرایی واقعی</label><select id="task-dependencies" name="dependencies" multiple>${options(c.tasks.filter(t=>canViewTask(c.actor,t)&&t.status!=='cancelled').map(t=>[t.id,t.title]),'')}</select></div></details>${d.preset==='external'?`<details open><summary>سفارش بیرون کارخانه</summary><div class="field"><label>طرف سفارش<input name="counterparty" required value="${esc(d.counterparty||'')}"></label></div><div class="field"><label>مخاطب پیگیری و راه ارتباطی<input name="contact" required value="${esc(d.contact||'')}"></label></div>${[['paymentOwner','مسئول پیگیری پرداخت'],['deliveryOwner','مسئول تحویل'],['designOwner','مسئول بررسی طراحی'],['advisor','مشاور']].map(([k,title])=>`<div class="field"><label>${title}<select name="${k}">${peopleOptions(d[k]||c.actor)}</select></label></div>`).join('')}<div class="field"><label>خروجی قابل تحویل و معیار قبول<textarea name="deliverable">${esc(d.deliverable||'')}</textarea></label></div></details>`:''}<div class="field-row"><div class="field"><label for="task-due">موعد · اختیاری</label><input id="task-due" name="due" type="datetime-local" value="${esc(d.due||'')}"></div><div class="field"><label for="task-priority">اولویت</label><select id="task-priority" name="priority">${options(['عادی','بالا','فوری'].map(x=>[x,x]),d.priority||'عادی')}</select></div></div><button type="button" class="post-media" data-action="task-media">${d.cover?`<img src="${esc(d.cover)}" alt="رسانه انتخاب‌شده"><span class="change-media">تغییر عکس</span>`:'افزودن عکس پست · اختیاری'}</button><input type="file" id="task-media-file" accept="image/*" hidden>`:'<p class="sheet-body-note">موضوع آماده یا سایر موارد را انتخاب کنید.</p>'}</form>`;
}
export function captureTaskForm(d,form){if(!form)return d;const fd=new FormData(form),next={...d};for(const key of ['title','description','material','purity','finish','quantity','weight','unitWeight','targetKind','path','endStage','ownerId','discrepancyOwnerId','due','priority','counterparty','contact','paymentOwner','deliveryOwner','designOwner','advisor','deliverable'])if(fd.has(key))next[key]=fd.get(key);next.targets=[0,1,2].map(i=>({sku:fd.get('target.'+i+'.sku'),quantity:fd.get('target.'+i+'.quantity'),unitWeight:fd.get('target.'+i+'.unitWeight')})).filter(r=>r.sku||r.quantity||r.unitWeight);next.team=fd.getAll('team');next.dependencies=fd.getAll('dependencies');next.responsibilities={};for(const[k,v]of fd)if(k.startsWith('responsibility.'))next.responsibilities[k.slice(15)]=v;return next;}
export const stageReasons=name=>name.includes('ذوب')?['نمونه‌برداری','مانده در بوته','پاشش یا چسبندگی','آلیاژ افزوده','سایر موارد']:name.includes('نورد')||name.includes('برش')?['نمونه‌برداری','لبه و براده قابل بازیافت','مانده در ابزار','سایر موارد']:name.includes('محلول')||name.includes('انحلال')||name.includes('کلرید')?['نمونه‌برداری','فلز در محلول','فیلتر یا رسوب قابل پیگیری','سایر موارد']:['نمونه‌برداری','مانده قابل بازیافت','اصلاح اندازه‌گیری','سایر موارد'];
export function reportMarkup(t,stage,actor){const prod=t.type==='production',pack=stage.name.includes('بسته‌بندی');const weights=[['input','ورودی همین نوبت'],['output','خروجی اصلی همین نوبت'],['added','افزودنی واقعی'],['sample','نمونه جداشده'],['untreated','مقدار فرآوری‌نشده'],['returned','برگشتی به صندوق'],['residue','مانده قابل بازیافت'],...(t.discrepancyOwnerId===actor?[['finalLoss','کسر قطعی توسط مسئول همین کار']]:[])];return `<form id="report-form" data-id="${esc(t.id)}" data-stage="${esc(stage.id)}" novalidate><div class="form-error" id="report-error" role="alert"></div><div class="field"><label for="report-title">عنوان گزارش</label><input id="report-title" name="title" required maxlength="100"></div><div class="field"><label for="report-text">شرح رسمی عملیات / تجربه</label><textarea id="report-text" name="text" maxlength="4000"></textarea></div><div class="field-row"><div class="field"><label for="report-kind">نوع رویداد</label><select id="report-kind" name="kind"><option value="start">شروع نوبت</option><option value="progress" selected>گزارش میانی / پیشروی جزئی</option><option value="complete">پایان همین نوبت</option><option value="experience">تجربه و R&D رسمی</option></select></div><div class="field"><label for="report-run">شناسه نوبت یا بچ جزئی</label><input id="report-run" name="runId" placeholder="مثلاً نوبت دوم همین کار"></div></div>${prod?`<div class="field"><label for="report-certainty">قطعیت وزن و فلز محتوی</label><select id="report-certainty" name="certainty">${options(Object.entries(certaintyNames),'unknown')}</select></div><div class="field-row">${weights.map(([key,label])=>`<div class="field"><label for="report-${key}">${label} · گرم</label><input id="report-${key}" name="${key}" inputmode="decimal"><small>خالی یعنی ثبت نشده؛ صفر فقط با ورود صریح عدد صفر</small></div>`).join('')}</div><div class="field-row"><div class="field"><label for="report-purity">عیار ثبت‌شده · در هزار · اختیاری</label><input id="report-purity" name="purity" inputmode="decimal"></div>${pack?'<div class="field"><label for="report-gross">وزن واقعی با بسته · گرم · الزامی</label><input id="report-gross" name="gross" inputmode="decimal" required></div>':''}</div><div class="field"><label for="report-reason">علت خاص این فرایند · در صورت اختلاف</label><select id="report-reason" name="reason"><option value="">هنوز علتی انتخاب نشده است</option>${options(stageReasons(stage.name).map(x=>[x,x]),'')}</select></div><div class="field"><label for="report-reason-text">توضیح علت و سایر موارد</label><textarea id="report-reason-text" name="reasonText"></textarea></div>`:''}<details><summary>تجربه و آموخته‌ها · اختیاری</summary><div class="field"><label>مسئله یا هدف آزمایش<textarea name="problem"></textarea></label></div><div class="field"><label>مشاهده عادی یا غیرعادی و دستاورد<textarea name="observation"></textarea></label></div><div class="field"><label>اقدام بعدی پیشنهادی<textarea name="nextAction"></textarea></label></div></details>${t.external?`<details open><summary>ثبت نتیجه مسئولیت بیرونی</summary><div class="field"><label>نقش این گزارش<select name="externalRole">${options([['','گزارش عمومی کار'],['paymentOwner','پیگیری پرداخت'],['deliveryOwner','تحویل و ارسال'],['designOwner','بررسی طراحی و فنی'],['advisor','راهنمایی مشاور']],'')}</select></label></div>${[['agreedAmount','مبلغ توافقی · ریال'],['actualAmount','مبلغ واقعاً پیگیری‌شده · ریال'],['approvedVersion','نسخه یا مشخصات تأییدشده'],['actualQuantity','تعداد واقعی نتیجه'],['deliveryDestination','مقصد تحویل واقعی'],['issue','مغایرت و نتیجه پیگیری']].map(([key,label])=>`<div class="field"><label>${label}<input name="${key}"></label></div>`).join('')}<small>این گزارش، مجوز پرداخت یا تأیید دریافت طرف مقابل ایجاد نمی‌کند.</small></details>`:''}<label class="field"><span><input type="checkbox" name="completeStage"> همه نوبت‌های این فرایند تمام شده‌اند</span></label><div class="field"><label for="report-photos">${pack?'عکس روی و پشت بسته · هر دو الزامی':'عکس یا آلبوم این رویداد · اختیاری'}</label><input id="report-photos" name="photos" type="file" accept="image/*" multiple ${pack?'required':''}><small>گزارش بدون الزام عکس، بدون تصویر هم ثبت می‌شود.</small></div></form>`;}
export function structuredReport(r,production=true){const fields=production?[['وزن خروجی',r.weight??r.output],['ورودی نوبت',r.inputWeight??r.input],['افزودنی',r.added],['نمونه',r.sample],['فرآوری‌نشده',r.untreated],['برگشت صندوق',r.returned],['مانده قابل بازیافت',r.residue],['کسر قطعی',r.finalLoss],['وزن با بسته',r.gross]]:[];return `<div class="report-fields">${fields.filter(([,v])=>v!==undefined).map(([k,v])=>`<span>${k}<b>${grams(r.rawWeights?.[({'وزن خروجی':'output','ورودی نوبت':'input','افزودنی':'added','نمونه':'sample','فرآوری‌نشده':'untreated','برگشت صندوق':'returned','مانده قابل بازیافت':'residue','کسر قطعی':'finalLoss','وزن با بسته':'gross'})[k]]??v)} گرم</b></span>`).join('')}${r.certainty?`<span>قطعیت <b>${esc(certaintyNames[r.certainty])}</b></span>`:''}${r.purity?`<span>عیار <b>${esc(r.purity)}</b></span>`:''}${r.runId?`<span>نوبت <b>${esc(r.runId)}</b></span>`:''}</div>${r.externalEvidence?`<div class="op-help">${[['نقش',r.externalEvidence.externalRole],['مبلغ توافقی',r.externalEvidence.agreedAmount],['مبلغ واقعی',r.externalEvidence.actualAmount],['نسخه تأییدشده',r.externalEvidence.approvedVersion],['تعداد واقعی',r.externalEvidence.actualQuantity],['مقصد',r.externalEvidence.deliveryDestination],['مغایرت',r.externalEvidence.issue]].filter(([,v])=>v).map(([label,value])=>`<b>${label}</b><p data-user-content>${esc(value)}</p>`).join('')}</div>`:''}${r.experience?`<div class="op-help">${[['مسئله',r.experience.problem],['مشاهده',r.experience.observation],['اقدام بعدی',r.experience.nextAction]].filter(([,v])=>v).map(([label,value])=>`<b>${label}</b><p data-user-content>${esc(value)}</p>`).join('')}</div>`:''}${r.reason||r.reasonText?`<div class="op-help"><b>${esc(r.reason||'علت اختلاف')}</b><p>${esc(r.reasonText||'')}</p></div>`:''}`;}
